# Pulumi ComponentResource: WebAppInfrastructure

## Project structure

```
webapp/
├── Pulumi.yaml
├── package.json
├── tsconfig.json
├── index.ts
├── components/
│   └── webapp.ts
├── config.ts
├── dev.yaml
└── prod.yaml
```

## `Pulumi.yaml`

```yaml
name: webapp
runtime: nodejs
description: Stateless web app infrastructure (S3 + RDS + IAM)
```

## Stack configs

**`dev.yaml`**

```yaml
config:
  webapp:environment: dev
  webapp:region: us-east-1
  webapp:dbInstanceClass: db.t3.micro
  webapp:dbMultiAz: false
  webapp:dbAllocatedStorage: 20
  webapp:bucketReplicaRegion: ""           # no replication in dev
  webapp:dbPassword:
    secure: AAABALnT7d...                  # Pulumi ConfigSecret (encrypted with stack key)
```

**`prod.yaml`**

```yaml
config:
  webapp:environment: prod
  webapp:region: us-east-1
  webapp:dbInstanceClass: db.t3.medium
  webapp:dbMultiAz: true
  webapp:dbAllocatedStorage: 50
  webapp:bucketReplicaRegion: us-west-2
  webapp:dbPassword:
    secure: AAABALm3x...                   # encrypted, never plaintext in git
```

## `config.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";

const cfg = new pulumi.Config();

export interface StackSettings {
    environment: "dev" | "prod";
    region: string;
    dbInstanceClass: string;
    dbMultiAz: boolean;
    dbAllocatedStorage: number;
    bucketReplicaRegion?: string;
    dbPassword: pulumi.Output<string>; // secret
}

export function getStackSettings(): StackSettings {
    const environment = cfg.require("environment") as "dev" | "prod";
    return {
        environment,
        region: cfg.require("region"),
        dbInstanceClass: cfg.require("dbInstanceClass"),
        dbMultiAz: cfg.getBoolean("dbMultiAz") ?? false,
        dbAllocatedStorage: cfg.getNumber("dbAllocatedStorage") ?? 20,
        bucketReplicaRegion: cfg.get("bucketReplicaRegion") || undefined,
        // requireSecret: fails loudly if accidentally stored unencrypted
        dbPassword: cfg.requireSecret("dbPassword"),
    };
}
```

## `components/webapp.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface WebAppComponentArgs {
    environment: "dev" | "prod";
    dbInstanceClass: string;
    dbMultiAz: boolean;
    dbAllocatedStorage: number;
    bucketReplicaRegion?: string;
    dbPassword: pulumi.Output<string>;
    tags?: Record<string, string>;
}

export class WebAppComponent extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.Bucket;
    public readonly bucketReplicationRoleArn?: pulumi.Output<string>;
    public readonly db: aws.rds.Instance;
    public readonly serviceRole: aws.iam.Role;
    public readonly connectionString: pulumi.Output<string>;

    constructor(name: string, args: WebAppComponentArgs, opts?: pulumi.ComponentResourceOptions) {
        super("webapp:infra:WebAppComponent", name, {}, opts);

        const tags = {
            Environment: args.environment,
            ManagedBy: "pulumi",
            ...args.tags,
        };

        // ------------------------------------------------------------------
        // 1. S3 bucket — versioned, encrypted, no public access
        // ------------------------------------------------------------------
        this.bucket = new aws.s3.Bucket(`${name}-assets`, {
            tags,
            versioning: { enabled: true },
            serverSideEncryptionConfiguration: {
                rule: {
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "aws:kms",
                        kmsMasterKeyId: aws.kms.Key ? undefined : undefined,
                    },
                    bucketKeyEnabled: true,
                },
            },
        }, { parent: this });

        const bucketPublicAccessBlock = new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-pab`,
            {
                bucket: this.bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            { parent: this },
        );

        // Cross-region replication (prod only)
        if (args.bucketReplicaRegion) {
            const replicaBucket = new aws.s3.Bucket(
                `${name}-assets-replica`,
                {
                    tags,
                    versioning: { enabled: true }, // required for replication target
                },
                { parent: this, provider: new aws.Provider(`${name}-replica-provider`, {
                    region: args.bucketReplicaRegion,
                })},
            );

            this.bucketReplicationRoleArn = new aws.iam.Role(
                `${name}-s3-replication-role`,
                {
                    tags,
                    assumeRolePolicy: JSON.stringify({
                        Version: "2012-10-17",
                        Statement: [{
                            Effect: "Allow",
                            Principal: { Service: "s3.amazonaws.com" },
                            Action: "sts:AssumeRole",
                        }],
                    }),
                    inlinePolicies: [{
                        name: "replication",
                        policy: this.bucket.arn.apply(bucketArn =>
                            JSON.stringify({
                                Version: "2012-10-17",
                                Statement: [{
                                    Effect: "Allow",
                                    Action: [
                                        "s3:GetReplicationConfiguration",
                                        "s3:ListBucket",
                                    ],
                                    Resource: bucketArn,
                                }, {
                                    Effect: "Allow",
                                    Action: [
                                        "s3:GetObjectVersionForReplication",
                                        "s3:GetObjectVersionAclForReplication",
                                        "s3:GetObjectVersionTaggingForReplication",
                                    ],
                                    Resource: `${bucketArn}/*`,
                                }, {
                                    Effect: "Allow",
                                    Action: [
                                        "s3:ReplicateObject",
                                        "s3:ReplicateDelete",
                                        "s3:ReplicateTags",
                                    ],
                                    Resource: pulumi.interpolate`${replicaBucket.arn}/*`,
                                }],
                            }),
                        ),
                    }),
                },
                { parent: this },
            ).arn;

            new aws.s3.BucketReplicationConfiguration(`${name}-assets-replication`, {
                role: this.bucketReplicationRoleArn,
                bucket: this.bucket.id,
                rules: [{
                    id: "replicate-all",
                    status: "Enabled",
                    destination: { bucket: replicaBucket.arn },
                    // ensure IAM/policy setup precedes replication config
                    filter: {},
                }],
            }, { parent: this, dependsOn: [bucketPublicAccessBlock] });
        }

        // ------------------------------------------------------------------
        // 2. RDS PostgreSQL — deletion protection, private, backed up
        // ------------------------------------------------------------------
        const dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-dbsubnets`, {
            tags,
            subnetIds: aws.getSubnetsOutput({ filters: [{ name: "default-for-az", values: ["true"] }] })
                .ids,
        }, { parent: this });

        const dbSecurityGroup = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            tags,
            description: "RDS access from VPC",
            ingress: [{
                protocol: "tcp",
                fromPort: 5432,
                toPort: 5432,
                cidrBlocks: ["10.0.0.0/8"], // VPC-internal only
            }],
            egress: [{
                protocol: "-1",
                fromPort: 0,
                toPort: 0,
                cidrBlocks: ["0.0.0.0/0"],
            }],
        }, { parent: this });

        this.db = new aws.rds.Instance(`${name}-db`, {
            tags,
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: args.dbInstanceClass,
            allocatedStorage: args.dbAllocatedStorage,
            storageEncrypted: true,
            multiAz: args.dbMultiAz,
            dbSubnetGroupName: dbSubnetGroup.name,
            vpcSecurityGroupIds: [dbSecurityGroup.id],
            username: "appuser",
            password: args.dbPassword, // secret, never in state plaintext
            publiclyAccessible: false,          // acceptance: not public
            deletionProtection: true,           // acceptance: deletion protection
            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-final-snapshot`,
            backupRetentionPeriod: 7,           // acceptance: >= 7 days
            backupWindow: "03:00-04:00",
        }, { parent: this });

        this.connectionString = pulumi.secret(
            pulumi.interpolate`postgresql://appuser:${args.dbPassword}@${this.db.address}:${this.db.port}/appdb`,
        );

        // ------------------------------------------------------------------
        // 3. IAM role — least privilege for the service
        // ------------------------------------------------------------------
        const leastPrivilegePolicy = pulumi.all([
            this.bucket.arn,
            this.db.arn,
        ]).apply(([bucketArn, dbArn]) => JSON.stringify({
            Version: "2012-10-17",
            Statement: [
                {
                    Sid: "BucketReadObjects",
                    Effect: "Allow",
                    Action: [
                        "s3:GetObject",
                        "s3:PutObject",
                    ], // explicit actions — no wildcards (prod criterion #4)
                    Resource: `${bucketArn}/*`,
                },
                {
                    Sid: "BucketList",
                    Effect: "Allow",
                    Action: ["s3:ListBucket", "s3:GetBucketLocation"],
                    Resource: bucketArn,
                },
                {
                    Sid: "DbDescribe",
                    Effect: "Allow",
                    Action: ["rds:DescribeDBInstances"],
                    Resource: dbArn,
                },
            ],
        }));

        this.serviceRole = new aws.iam.Role(`${name}-service-role`, {
            tags,
            assumeRolePolicy: JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: {
                        // OIDC trust for service accounts (prod); sts AssumeRole for dev
                        ...(args.environment === "prod"
                            ? { Federated: "arn:aws:iam::ACCOUNT:oidc-provider/oidc.eks.us-east-1.amazonaws.com" }
                            : { Service: "ec2.amazonaws.com" }),
                    },
                    Action: "sts:AssumeRoleWithWebIdentity",
                }],
            }),
        }, { parent: this });

        new aws.iam.RolePolicy(`${name}-service-policy`, {
            role: this.serviceRole.id,
            policy: leastPrivilegePolicy,
        }, { parent: this });

        this.registerOutputs({
            bucketName: this.bucket.id,
            dbAddress: this.db.address,
            serviceRoleArn: this.serviceRole.arn,
            connectionString: this.connectionString,
        });
    }
}
```

## `index.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import { WebAppComponent } from "./components/webapp";
import { getStackSettings } from "./config";

const settings = getStackSettings();

const app = new WebAppComponent(`webapp-${settings.environment}`, {
    environment: settings.environment,
    dbInstanceClass: settings.dbInstanceClass,
    dbMultiAz: settings.dbMultiAz,
    dbAllocatedStorage: settings.dbAllocatedStorage,
    bucketReplicaRegion: settings.bucketReplicaRegion,
    dbPassword: settings.dbPassword,
});

// Stack-level outputs
export const bucketName = app.bucket.id;
export const dbAddress = app.db.address;
export const serviceRoleArn = app.serviceRole.arn;
export const connectionString = app.connectionString; // marked secret
```

